from os import path

from taf.gnb.oam.coam.cu.interfaces.cuoam22r4 import CUOAM22R4
from taf.gnb.oam.coam.cu.schemas.internal.asm.get_operation_history_response import (
    GetOperationHistoryResponse,
)
from taf.gnb.oam.coam.cu.schemas.internal.asm.staged_plan_validation_ressults_asm_v1 import (
    CUStagedPlanValidationResultsASMV1,
)
from taf.gnb.oam.coam.cu.schemas.licensed.asm.get_snapshot_operations_information import (
    GetSnapshotOperationsInformationV1,
)
from taf.gnb.oam.coam.cu.services.licensed.asm.asm_licensed_v1 import ASM_LICENSEDv1
from taf.gnb.oam.coam.cu.schemas.licensed.asm.get_cu_state_v1 import (
    GetCUStateASMLicensedV1,
)
from taf.gnb.oam.coam.cu.schemas.internal.asm.cu_states_response_v1 import CuStatesASMV1

from taf.gnb.oam.coam.cu.utilities.poll_status import poll_status
from taf.gnb.oam.coam.cu.services.internal.emservice.emservice_v1 import EMServicev1

from taf.gnb.oam.coam.cu.exception import ApiException


class CUOAM23R1(CUOAM22R4):
    def __init__(self, con_details):
        super(CUOAM23R1, self).__init__(con_details)
        self.con_details = con_details
        self.asm_licensed_v1 = ASM_LICENSEDv1(con_details=con_details)
        self.emservice_v1 = EMServicev1(con_details=con_details)

    def get_latest_validation_result_of_delta_plan(self, plan_id, error_type, timeout=30, page_number=1,
                                                   items_per_page=20000, sort_order='desc', sorted_by=''):
        validation_results = self.asm_v1.get_latest_validation_result_of_delta_plan(plan_id=plan_id,
                                                                                    error_type=error_type,
                                                                                    timeout=timeout,
                                                                                    page_number=page_number,
                                                                                    items_per_page=items_per_page,
                                                                                    sort_order=sort_order,
                                                                                    sorted_by=sorted_by)
        return CUStagedPlanValidationResultsASMV1.from_object_dict(validation_results)

    def get_cu_operation_history(self, timeout=30, raw=False):
        response = self.asm_v1.get_cu_operation_history(timeout=timeout)
        return response if raw else GetOperationHistoryResponse.from_object_dict(response).to_dict()

    def check_snapshot_status(self, timeout=30):
        return self.asm_licensed.check_snapshot_status(timeout=timeout)["status"]

    def get_snapshot_operations_information(self, timeout=30, raw=False):
        response = self.asm_licensed.get_snapshot_operations_information(timeout=timeout)

        return response if raw else GetSnapshotOperationsInformationV1.from_object_dict(response)

    def perform_commissioning(self, scf_file, wait_for_completion, should_activate=True, timeout=300):
        try:
            return self.asm_licensed_v1.perform_commissioning(scf_file=scf_file,
                                                              wait_for_completion=wait_for_completion,
                                                              should_activate=should_activate,
                                                              timeout=timeout)
        except ApiException as e:
            if "Machine-to-Machine interface was disabled" in e.body:
                return self._perform_commissioning_using_internal_api(scf_file=scf_file,
                                                                      wait_for_completion=wait_for_completion,
                                                                      timeout=timeout)
            else:
                raise e

    def _perform_commissioning_using_internal_api(self, scf_file, wait_for_completion, timeout):
        try:
            return self.asm_v1.perform_commissioning(scf_file=scf_file,
                                                     wait_for_completion=wait_for_completion,
                                                     timeout=timeout)
        except ApiException as e:
            # due to CB012840 /api/asm/v1/staged-plans might be unavailable then /api/emservice/v1/staged-plans
            # should be used instead
            if "No API found with those values API" in e.body:
                return self._combine_asm_and_emservice_api_to_perform_commissioning(scf_file=scf_file,
                                                                                    wait_for_completion=wait_for_completion,
                                                                                    timeout=timeout)
            else:
                raise e

    def _combine_asm_and_emservice_api_to_perform_commissioning(self, scf_file, wait_for_completion, timeout):
        plan_name = path.splitext(path.split(scf_file)[1])[0]

        self.asm_v1.add_plan_to_staging(scf_file=scf_file, plan_name=plan_name, timeout=timeout)
        staged_plans = self.emservice_v1.get_staged_plans()
        operation = self.asm_v1.activate_staged_plan(staged_plans=staged_plans,
                                                     plan_name=plan_name,
                                                     timeout=timeout)
        if wait_for_completion:
            method_name = "get_status_of_perform_commissioning"

            return poll_status(instance=self.asm_v1.local_client,
                               method_name=method_name,
                               operation_id=operation["id"],
                               timeout=timeout,
                               plan_id=operation["planId"])

        return operation

    def get_status_of_perform_commissioning(self, operation_id, should_activate=True, timeout=30):
        return self.asm_licensed_v1.get_status_of_perform_commissioning(operation_id=operation_id,
                                                                        should_activate=should_activate,
                                                                        timeout=timeout)

    def perform_delta_recommissioning(self, delta_file, wait_for_completion=True, should_activate=True, timeout=300):
        return self.asm_licensed_v1.perform_delta_recommissioning(delta_file=delta_file,
                                                                  wait_for_completion=wait_for_completion,
                                                                  should_activate=should_activate,
                                                                  timeout=timeout,
                                                                  nidd_info=self.get_nidd())

    def get_status_of_perform_delta_recommissioning(self, operation_id, timeout=30, should_activate=True):
        return self.asm_licensed_v1.get_status_of_perform_delta_recommissioning(operation_id=operation_id,
                                                                                timeout=timeout,
                                                                                should_activate=should_activate)

    def get_cu_state(self, use_m2m=True, raw=False):
        if use_m2m:
            cu_state = self.asm_licensed_v1.get_cu_state()
            return cu_state if raw else GetCUStateASMLicensedV1.from_object_dict(cu_state).to_dict()
        else:
            cu_state = self.asm_v1.get_cu_state()
            return cu_state if raw else CuStatesASMV1.from_object_dict(cu_state).to_dict()

    def get_active_software_version(self, use_m2m=True):
        if use_m2m:
            return self.asm_licensed_v1.get_active_software_version()
        else:
            return self.asm_v1.get_active_software_version()
